import{_ as a,C as o,o as r,c as s,j as t,a as n,E as l,a6 as i}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"你大约还有36个月的时间去成就自己","description":"","frontmatter":{"title":"你大约还有36个月的时间去成就自己","originalTitle":"You have about 36 months to make it","date":"2025-07-22","originalUrl":"https://thedankoe.com/letters/you-have-about-36-months-to-make-it/","minutes":10,"sourceHash":"a6bec158261aecf9f5859cb08c1cf37ee3cbde7732cea8242feaaf9455d9993c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-have-about-36-months-to-make-it/"}]]},"headers":[],"relativePath":"letters/you-have-about-36-months-to-make-it.md","filePath":"letters/you-have-about-36-months-to-make-it.md"}'),m={name:"letters/you-have-about-36-months-to-make-it.md"};function h(c,e,d,u,A,f){const p=o("ArticleMeta");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"你大约还有36个月的时间去成就自己",tabindex:"-1"},[n("你大约还有36个月的时间去成就自己 "),t("a",{class:"header-anchor",href:"#你大约还有36个月的时间去成就自己","aria-label":'Permalink to "你大约还有36个月的时间去成就自己"'},"​")],-1)),l(p),e[1]||(e[1]=i('<p>我一直在网上看到这样一句话流传:</p><p><em>「你大约还有36个月的时间去成就自己。」</em></p><p>这话有其道理:无论人们如何抵抗,AI都在并将继续取代工作。我们所熟知的金钱形式将会改变,甚至彻底消失,因为数以百万计的ASI(人工超级智能)将以超越人类理解能力的速度执行任务,主导人类的未来(参见:<a href="https://ai-2027.com/" target="_blank" rel="noreferrer">AI 2027</a>)。顺带一提,这也是你最后一次见到加密货币出现荒谬涨幅的机会,因为这项技术正在被采纳和监管。一旦被采纳,它就会变得像股票一样。</p><p>我写这封信的目的不是要吓唬你,也不是想制造轰动效应。所有这些都是预测和推测。它完全可能是错的,而且我预计其中大部分确实会出错。我只是在描述互联网某些小众角落正在发生的讨论场景。我希望能给你提供一个非教条式的视角,让你能够察觉机会,做出不会让自己陷入困境的决定,因为很明显<em>某些事情</em>正在改变,而未来将会以惊人的速度到来。</p><p>我不认为你有36个月的时间去「成就自己」。</p><p>相反,我认为你有36个月的时间,在此之后「成就自己」的定义将被彻底改写。</p><p>幸运的是,人性始终不变,我不禁认为这段快速增长的时期正标志着机器与人类之间一道清晰的分界线。</p><p>那些拥抱自己人性的人将会蓬勃发展。</p><p>而那些无法停止用机械化方式生活来定义自己的人,则不会。</p><h3 id="执行者-vs-指挥者" tabindex="-1">执行者 vs 指挥者 <a class="header-anchor" href="#执行者-vs-指挥者" aria-label="Permalink to &quot;执行者 vs 指挥者&quot;">​</a></h3><blockquote><p>我们很快就会看到10人团队创造10亿美元公司的现象……在我和科技公司CEO朋友们的一个群聊里,大家在打赌哪一年会出现第一家由一个人创造的10亿美元公司。</p><p>—— 山姆·奥特曼(Sam Altman)</p></blockquote><p>有一件事是确定的:</p><p>今天一个人所拥有的力量,远远超过过去任何时刻,而且这种力量只会持续增加。这种权力的转移经历了三个层次。</p><p><strong>互联网</strong>让人们能够获取一切知识。权力从学校和机构手中转移出来。</p><p><strong>社交媒体</strong>给了人们吸引自己受众的杠杆。权力从雇主、出版商、中心化媒体,甚至唱片公司手中转移出来。人们现在可以在不依赖他人权威的情况下学习、建设和赚钱。</p><p><strong>人工智能</strong>正赋予人们创造、自动化和外包几乎任何事情的能力。权力正在从传统的把关人和中介手中转移出来。人们很快将能够以极少的人力,运作出与大团队相当的水平。</p><p>简而言之,你现在拥有三种超能力来掌控自己的未来。</p><ul><li>学习——适应并弄清楚必须采取哪些行动才能获得特定结果的能力。</li><li>说服——建立信任、吸引人们认同一个互利愿景或叙事的能力。</li><li>执行——通过自动化、创造和委派,把想法变成现实的能力。</li></ul><p>这在那些会蓬勃发展和那些不会的人之间划出了一条清晰的分界线。</p><p>执行者 vs 指挥者。雇员 vs 创业者。低能动性 vs 高能动性。那些分配工作而不是被分配工作的人。那些追随自己的兴趣、同时做很多事情的人。那些不需要许可就能解决问题的人——由于随着现实变得越来越复杂,新问题不断涌现,而AI正在把这种复杂性加速推向无限,所以问题是无限的,因此以解决方案形式存在的价值也是无限的。金钱,不是作为美元,而是作为价值交换,实际上同样是无限的。</p><p>那些为未来的问题做好准备的人会赢——即使没有人能确切知道那些问题会是什么。简单明了。<a href="https://letters.thedankoe.com/p/full-course-the-one-person-business?lli=1" target="_blank" rel="noreferrer">「一人企业发射台」课程正是为此而设。</a></p><h3 id="品味是新的智力" tabindex="-1">品味是新的智力 <a class="header-anchor" href="#品味是新的智力" aria-label="Permalink to &quot;品味是新的智力&quot;">​</a></h3><p>反AI的人群终将失败。</p><p>将会有一群情绪激动的人群起哄,试图抹黑那些试图在工作中,尤其是创意工作中运用AI的人。忽视这些人,也别成为他们中的一员,因为在接下来的几年里保持悲观心态只会导致一种具有破坏性的确认偏误。你会变成你所专注的东西,而如果你专注于试图从山脚下阻止一场雪崩,你只会被压垮。</p><p>这些人尚未理解的是,我们创作的方式正在演变——这在此之前也发生过。摄影和视频在人类的时间尺度上都是极其新近的发展。修图软件和电脑生成图像让我们能够只需点击几下按钮就创造出如此不真实的场景。是的,创造那些东西并不容易,但比几年前容易多了。仅仅因为屏幕上的几次点击正在被自然语言取代,并不意味着创造我们视为艺术的东西变得更容易了,尤其是当我们对艺术的看法本身也在随文化变化,而文化正在此刻迅速转变。<strong>我们不会因为一个人使用某种特定工具而认定他是艺术家。</strong><em>我们认定一个人是艺术家,是因为</em><em><strong>为什么</strong></em><em>以及</em><em><strong>如何</strong></em><em>使用这个工具</em>。我们根据最终成品来评判他们。故事。情感。愿景。灵魂。而不是创作过程中投入的劳动时长。你可以花10年或10秒钟写一本书,并自称作者,但这不代表这本书是好书。</p><p>这就是反AI人群搞错的地方。</p><p>他们把所有使用AI的人都归为同一类。他们把AI看作一个用于输入短句的聊天框——比如打「帮我写这篇通讯」或「帮我生成这张图片」——虽然这些请求的输出结果可能在视觉上很吸引人,但那不代表它们就是艺术。<em>这恰恰暴露出,大多数人过度强调了创造视觉上美观事物所需的劳动过程,以至于这已经成为他们的身份认同,而人们会拼死拼活地捍卫这种身份,不愿放弃对自己的这种限制</em>。我不认为艺术应该与人们按下的工具按钮绑定,而应该与他们<em>为什么</em>按下那一系列特定按钮绑定。</p><p>我想我们都能同意,把所有思考和控制都外包给AI不会让你走到任何地方,但那些执着于这一点的人,并没有理解AI本质之外的任何东西。他们没有看到AI已经成为一种针对语言本身的编程语言。他们没有看到你可以给AI下极其具体的指令,精确到你能完全掌控输出结果(这其实就是大多数受雇的「创意工作」的本质——你在执行你自己没有设定的项目指令,这不是艺术,而是披着「艺术家」职位外衣的工业劳动)。</p><p>他们不明白,一个<em>词语</em>就是新的笔触,新的低通滤镜,新的选择与蒙版工具。他们不明白,艺术家为作品注入个人风格的每一个微小决定,依然存在,而且他们能够创造出超越自己最狂野梦想的作品,而不需要花费数小时去完成,但他们就是看不到那些随意生成的文本框之外的东西。</p><p><strong>将艺术与垂手可得的垃圾内容(slop)区分开来的唯一标准,就是品味。</strong></p><p>换句话说,什么都没有改变。人们只是憎恨新事物,而这个新事物正照亮了从一开始就真正重要的东西。如果你不能用AI创作艺术,那你从一开始就不是艺术家。你只是擅长使用一个工具而已。工具是会被替代的。</p><h3 id="效用-vs-意义" tabindex="-1">效用 vs 意义 <a class="header-anchor" href="#效用-vs-意义" aria-label="Permalink to &quot;效用 vs 意义&quot;">​</a></h3><p>硅解决效用问题,好让碳能够升华到意义层面。</p><p>我们讨厌车管所的长队。我们讨厌服务员把订单弄错。我们讨厌那些本可以用一封5点式邮件解决的会议。AI和自动化解决的正是人类厌恶的那些必要工作。而另一方面,我们渴望失败的可能性。我们喜爱九局下半的最后一位击球手。我们跨越半个地球去追求一场五星级的用餐体验。我们在婚礼上,听新郎新娘朗读手写誓言时流泪。</p><p>机器代表速度、重复和必需性。</p><p>人类代表故事、新奇、神话和意义。</p><p>大多数人把自己的身份认同建立在机器的特质上——上学、上班、做那些平凡琐碎的任务——这正是为什么普遍的幸福感如此糟糕的原因。这场变革会带来大量的动荡,那些还没有掌控好自己心智的人对此不会感到高兴,但我们已经集体憎恨工业化生活方式好几十年了。你没有资格抱怨,因为有99%的概率,你的生活会比今天好得难以想象。</p><p>放近了看是恐怖的,拉远了看是美好的。</p><p>当机械性的工作被取代后,剩下的就是意义。</p><p>要想弄清楚自己在生活中想要什么,就选择一件你深切关心的事情,毫不留情地把它剖析清楚,并毫不羞怯地把你的故事、价值观、愿景以及随之而来的人生作品公开分享出去,与一小群支持你所做之事的人一起,形成一种手工艺人式的生活方式。把这与AI结合起来,你就能腾出空间去享受闲暇——这正是创造性工作的终极补充。</p><h3 id="如何做好准备" tabindex="-1">如何做好准备 <a class="header-anchor" href="#如何做好准备" aria-label="Permalink to &quot;如何做好准备&quot;">​</a></h3><p>36个月去成就自己。</p><p>这个数字不是铁板一块,但它已经是你能得到的最准确的估计了。</p><p>你可以选择继续做你一直在做的事,也可以把这当作一个紧迫的时刻,彻底改变自己的人生。就我个人而言,我不明白你为什么不选第二种。改变你的生活、为自己铺就一个不可思议的未来,并不需要你放下一切、搬到国家的另一端。它需要你选择自己的工作。它需要你思考。它需要你去追求你所在乎的事情。它需要你去冒险,创造一个值得讲述的故事,并把它分享给那些能从中受益的人。</p><p>过去所有创造出「美好生活」的要素,如今正在变成一种必需品。</p><p><strong>1)成为一名哲人建造者(philosopher-builder)</strong></p><p>在当今世界,我们通常会尊重两类人。</p><p>程序员 vs 营销人员。大局观 vs 技术细节。精神层面 vs 实用层面。哲学家 vs 科学家。</p><p>未来要求我们把这些两极融合起来。建造者一直都需要思考者。一个没有配上营销人员的程序员,几乎总会导致用户数量令人失望。一个困于云端的嬉皮士和一个困于原子中的科学家,都同样错失了真相。那些能够体现这种二元性的人将变得无可阻挡,而我们已经看到这种现象在发生。</p><p>职位名称正在从「设计师」和「工程师」融合为「设计工程师」。这些工具,无论是否由AI驱动,都已经发展到一个阶段,人们无需增加劳动时间就能完成更多事情。</p><p>创作者在创办和推动公司发展。程序员在社交媒体上创造出数百万的浏览量。</p><p>人类能力的顶峰在于成为一个「专精的通才」。既不能专精到瞬间就被替代或因被贴上某个资历标签而被人利用,也不能通才到对任何事情都无法真正有效。</p><p><strong>2)成为想法的过滤器</strong></p><p>如今,想法比执行更重要。</p><p>如果说品味是新的智力,而策展是这个信息过载、任何人都能创造任何东西的世界里的新智商测试,那么选择<em>哪些想法值得被执行</em>,就应该在这张桌子上占据第一个座位。</p><p>你的思维必须变成一个精细调校的信噪比过滤器。</p><p>要做到这一点,你必须明白,你的思维是基于你的身份和世界观来解读现实的。你的价值观和信念。你所遵循的行为准则。你的发展水平。你正试图实现的愿景。当信息对你的主要目标和总体目标有用时,你的大脑就会释放多巴胺。</p><p>由于大多数人没有目标,或者他们的目标是由学校和工作分配的,这是一个极其痛苦的过程,只有那些<a href="https://letters.thedankoe.com/p/this-single-decision-will-determine?lli=1" target="_blank" rel="noreferrer">致力于反抗人生默认路径</a>的人,才会开始以某种方式调校自己的直觉,从而能够捕捉并利用面向未来的想法。</p><p>要知道哪些想法值得执行,唯一的方法就是在反复试错的烈火中锻造出你自己的哲学。</p><p><strong>3) 成为一名AI协调者</strong></p><p>在采用AI时,首要且基础的决定在于:何时利用它,何时亲自动手去做。</p><p>通常,这个决定取决于你喜欢做什么。对我来说,那就是写作。虽然我有各种用于研究和构思想法的提示词(我最喜欢的一个,是把我给它的主题输入进去,然后让它提出观察性的问题,直到我个人达到一个可以用在写作中的&quot;啊哈&quot;时刻),但我所有的书信都是亲手写的。AI是一个<em>增强</em>我写作的工具,而不是取代它。</p><p>在我的手艺之外,我把AI提示词看作是高度专业化的员工。我讨厌营销,所以我用我尊重的营销人员的信息来训练AI,给它我的框架、案例或灵感来源,然后让它吐出一份初稿,我再根据直觉和品味进行打磨。到最后,质量更高了,但和我自己动手做出来的东西相比,差别并不大。</p><p>专精于你的手艺,协调一支符合你价值观和愿景的、有品味的提示词舰队。</p><p>如果你还没开始,学习AI的最佳方式就是尝试把自己的工作自动化到失业。</p><p>是的,这会增加你现在的工作被取代的可能性,但如果你能把它自动化,你反正也会被取代的,而且这至少能让你提升技能,达到获得晋升或者能够为自己工作的程度。</p><p>我会在未来的书信中继续深入探讨这些内容。</p><p>感谢你阅读这一篇。</p><p>——丹</p><hr><p><a href="/en/letters/you-have-about-36-months-to-make-it">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',71))])}const I=a(m,[["render",h]]);export{g as __pageData,I as default};
